def choose_num(x, y):
    res = y if y % 2 == 0 else y - 1
    return res if res >= x else -1

def histogram(test):
    counts = {}
    for char in test.split():
        counts[char] = counts.get(char, 0) + 1
    if not counts:
        return {}
    max_count = max(counts.values())
    return {k: v for k, v in counts.items() if v == max_count}

def max_fill(grid, capacity):
    total_drops = 0
    for row in grid:
        water_units = sum(row)
        total_drops += (water_units + capacity - 1) // capacity
    return total_drops

def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels and word[i-1] not in vowels and word[i+1] not in vowels:
            return word[i]
    return ""

def maximum(arr, k):
    if k == 0:
        return []
    return sorted(arr)[-k:]

def prod_signs(arr):
    if not arr:
        return None
    sign_product = 1
    magnitude_sum = 0
    for x in arr:
        magnitude_sum += abs(x)
        if x == 0:
            return 0
        elif x < 0:
            sign_product *= -1
    return magnitude_sum * sign_product

def digits(n):
    product = 1
    has_odd = False
    for digit in str(n):
        d = int(digit)
        if d % 2 != 0:
            product *= d
            has_odd = True
    return product if has_odd else 0

def can_arrange(arr):
    for i in range(len(arr) - 1, 0, -1):
        if arr[i] < arr[i-1]:
            return i
    return -1

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    return " ".join(word for word in words if is_prime(len(word)))

def do_algebra(operator, operand):
    expr = str(operand[0])
    for op, val in zip(operator, operand[1:]):
        expr += f" {op} {val}"
    return eval(expr)

def sort_third(l: list):
    third_elements = sorted(l[i] for i in range(0, len(l), 3))
    res = l[:]
    for i, val in enumerate(third_elements):
        res[i * 3] = val
    return res

