def prime_fib(n: int):
    count = 0
    a, b = 0, 1
    while True:
        if a > 1:
            is_prime = True
            for i in range(2, int(a**0.5) + 1):
                if a % i == 0:
                    is_prime = False
                    break
            if is_prime:
                count += 1
                if count == n:
                    return a
        a, b = b, a + b

def change_base(x: int, base: int):
    if x == 0:
        return '0'
    digits = []
    while x > 0:
        digits.append(str(x % base))
        x //= base
    return ''.join(reversed(digits))

def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if not numbers:
        return []
    result = []
    for i, num in enumerate(numbers):
        result.append(num)
        if i < len(numbers) - 1:
            result.append(delimeter)
    return result

